// Build price map from the Ingredients sheet
const ingredients = $('Read ingredients').all().map((i) => i.json);
const recipes = $('Read recipes').all().map((i) => i.json);
const menu = $('Read menu').all().map((i) => i.json);

const priceMap = {};
for (const row of ingredients) {
  if (row.ingredient) priceMap[String(row.ingredient).trim()] = Number(row.unit_price);
}

// Sum theoretical cost per menu item, and keep the per-ingredient breakdown
const costMap = {};
const breakdown = {};
const missing = new Set();
for (const row of recipes) {
  const dish = String(row.menu_item || '').trim();
  const ing = String(row.ingredient || '').trim();
  if (!dish || !ing) continue;
  const unitPrice = priceMap[ing];
  if (unitPrice === undefined || Number.isNaN(unitPrice)) {
    missing.add(`${dish}: "${ing}" not found in Ingredients sheet`);
    continue;
  }
  const qty = Number(row.quantity || 0);
  const subtotal = unitPrice * qty;
  costMap[dish] = (costMap[dish] || 0) + subtotal;
  (breakdown[dish] = breakdown[dish] || []).push({
    ingredient: ing,
    quantity: qty,
    unit_price: unitPrice,
    subtotal: Math.round(subtotal),
  });
}

const today = $now.toFormat('yyyy-MM-dd');

return menu
  .filter((m) => m.menu_item)
  .map((m) => {
    const dish = String(m.menu_item).trim();
    const price = Number(m.selling_price) || 0;
    const cost = Math.round(costMap[dish] || 0);
    const ratio = price > 0 ? Math.round((cost / price) * 1000) / 10 : 0;
    const target = Number(m.target_cost_ratio) || 30;
    const over = ratio > target;

    // Which ingredient carries the most of this dish's cost
    const parts = (breakdown[dish] || []).slice().sort((a, b) => b.subtotal - a.subtotal);
    const top = parts[0];
    const topShare = top && cost > 0 ? Math.round((top.subtotal / cost) * 100) : 0;

    // Selling price that would bring this dish back to its target (calculated, not guessed)
    const priceToHitTarget = target > 0 ? Math.ceil(cost / (target / 100)) : 0;

    return {
      json: {
        row_number: m.row_number,
        menu_item: dish,
        selling_price: price,
        target_cost_ratio: target,
        theoretical_cost: cost,
        current_cost_ratio: ratio,
        status: over ? 'OVER' : 'OK',
        over,
        last_checked: today,
        missing_ingredients: [...missing].join('; '),
        breakdown: parts,
        top_ingredient: top ? top.ingredient : '',
        top_ingredient_share: topShare,
        price_to_hit_target: priceToHitTarget,
      },
    };
  });

const items = $input.all().map((i) => i.json);
const over = items.filter((i) => i.status === 'OVER');
const missing = items[0]?.missing_ingredients || '';

// Numbers are stated here, not by the AI, so they are always exact
const lines = over.map(
  (i) =>
    `- ${i.menu_item}: ${i.current_cost_ratio}% (target ${i.target_cost_ratio}%) | cost ${i.theoretical_cost} yen / price ${i.selling_price} yen`
);

let body = '';
if (over.length > 0) {
  body = `The following menu item(s) are over their target cost ratio:\n\n${lines.join('\n')}\n\nChecked ${items.length} menu items today.`;
  if (missing) body += `\n\n[!] Recipe rows skipped (name mismatch): ${missing}`;
}

// Facts handed to the AI. Every number here is already calculated.
const facts = over
  .map((i) => {
    const parts = (i.breakdown || [])
      .slice(0, 4)
      .map((b) => `${b.ingredient} ${b.quantity} x ${b.unit_price} = ${b.subtotal} yen`)
      .join(', ');
    return [
      `Dish: ${i.menu_item}`,
      `  cost ratio now ${i.current_cost_ratio}% / target ${i.target_cost_ratio}%`,
      `  theoretical cost ${i.theoretical_cost} yen, selling price ${i.selling_price} yen`,
      `  biggest cost driver: ${i.top_ingredient} (${i.top_ingredient_share}% of this dish's cost)`,
      `  selling price that would restore the target: ${i.price_to_hit_target} yen`,
      `  ingredients: ${parts}`,
    ].join('\n');
  })
  .join('\n\n');

return [
  {
    json: {
      overCount: over.length,
      subject: `Cost ratio alert: ${over.length} menu item(s) over target`,
      emailBody: body,
      facts,
    },
  },
];

