// Rescue the JSON whatever the model wrapped it in
const raw = $input.first().json.content.parts[0].text;
const m = String(raw).match(/\{[\s\S]*\}/);
if (!m) throw new Error('The model did not return JSON. Raw output: ' + String(raw).slice(0, 300));

let doc;
try {
  doc = JSON.parse(m[0]);
} catch (e) {
  throw new Error('Could not parse the extracted JSON: ' + e.message);
}

// Convert every line to a price per base unit (gram / ml / piece)
const FACTOR = { kg: 1000, g: 1, l: 1000, ml: 1, case: 1, box: 1, bag: 1, pc: 1, pcs: 1, piece: 1 };
const BASE   = { kg: 'g', g: 'g', l: 'ml', ml: 'ml', case: 'piece', box: 'piece', bag: 'piece', pc: 'piece', pcs: 'piece', piece: 'piece' };

const allRows = doc.line_items || [];
const unreadableCount = allRows.filter((r) => r.unreadable === true).length;
const lines = allRows
  .filter((r) => r.unreadable !== true && String(r.ingredient || '').trim())
  .map((r) => {
    const unitRaw = String(r.unit || 'pc').trim().toLowerCase();
    const factor = FACTOR[unitRaw] ?? 1;
    const base = BASE[unitRaw] ?? unitRaw;
    const qty = Number(r.quantity) || 0;
    const lineTotal = Number(r.line_total) || (Number(r.unit_price) || 0) * qty;
    const baseQty = qty * factor;
    return {
      ingredient: String(r.ingredient).trim(),
      quantity: qty,
      unit_as_printed: unitRaw,
      unit: base,
      unit_price: baseQty > 0 ? Math.round((lineTotal / baseQty) * 10000) / 10000 : 0,
      line_total: Math.round(lineTotal),
    };
  });

// Check the document against itself before touching the master sheet
const sumLines = lines.reduce((s, r) => s + r.line_total, 0);
const subtotal = Math.round(Number(doc.subtotal) || 0);
const total = Math.round(Number(doc.invoice_total) || 0);
// Line items add up to the pre-tax subtotal on most notes; compare against that when it is printed,
// and fall back to the grand total when it is not.
const stated = subtotal > 0 ? subtotal : total;
const gap = Math.abs(sumLines - stated);
const tolerance = Math.max(1, Math.round(stated * 0.01)); // 1% or 1 yen, whichever is larger
// No unreadable rows: the readable rows must add up exactly (a mismatch means a misread digit).
// Some unreadable rows: the readable rows just must not exceed the subtotal; they are written and
// the unreadable ones are reported for a human to add by hand.
const balanced = stated > 0 && (
  unreadableCount === 0 ? gap <= tolerance : sumLines <= stated + tolerance
);

return [{
  json: {
    is_invoice: doc.is_invoice !== false,
    supplier: doc.supplier || '',
    invoice_date: doc.invoice_date || $now.toFormat('yyyy-MM-dd'),
    subtotal,
    invoice_total: total,
    compared_against: stated,
    line_sum: sumLines,
    gap,
    balanced,
    line_count: lines.length,
    unreadable_count: unreadableCount,
    lines,
    file_name: $('New invoice photo in Drive').first().json.name || '',
  },
}];

